async function generateStaticParams(
  categories: CategoryTree[] = []
): Promise<RouteParams[]> {
  const results: RouteParams[] = [];

  const collectPaths = (nodes: ArticleNode[], prefix: string[]): string[][] => {
    const paths: string[][] = [];
    if (!Array.isArray(nodes)) return paths;

