type DynamicOption = 'auto' | 'force-dynamic' | 'error' | 'force-static';
type RevalidateOption = false | 0 | number;
type FetchCacheOption =
  | 'auto'
  | 'default-cache'
  | 'only-cache'
  | 'force-cache'
  | 'force-no-store'
  | 'default-no-store'
  | 'only-no-store';

interface SegmentConfig {
  segmentPath: string;
  dynamic?: DynamicOption;
  revalidate?: RevalidateOption;
  fetchCache?: FetchCacheOption;
}

interface ResolvedRouteConfig {
  effectiveDynamic: DynamicOption;
  effectiveRevalidate: RevalidateOption;
  effectiveFetchCache: FetchCacheOption;
  routeMode: 'static' | 'isr' | 'dynamic';
  hasConflict: boolean;
  conflictReason?: string;
}

function resolveRouteSegmentConfig(segments: SegmentConfig[] = []): ResolvedRouteConfig {
  let effectiveDynamic: DynamicOption = 'auto';
  let effectiveRevalidate: RevalidateOption = false;
  let effectiveFetchCache: FetchCacheOption = 'auto';

  let hasForceDynamic = false;
  let hasForceStatic = false;
  let hasRevalidateZero = false;
  let minPositiveRevalidate: number | null = null;
  let forceFetchCache: FetchCacheOption | null = null;
  let lastFetchCache: FetchCacheOption | null = null;
  let lastDynamic: DynamicOption | null = null;

  for (const seg of segments) {
    if (!seg) continue;

    if (seg.dynamic) {
      lastDynamic = seg.dynamic;
      if (seg.dynamic === 'force-dynamic') hasForceDynamic = true;
      if (seg.dynamic === 'force-static') hasForceStatic = true;
    }

    if (seg.revalidate !== undefined) {
      if (seg.revalidate === 0) {
        hasRevalidateZero = true;
      } else if (typeof seg.revalidate === 'number' && seg.revalidate > 0) {
        if (minPositiveRevalidate === null || seg.revalidate < minPositiveRevalidate) {
          minPositiveRevalidate = seg.revalidate;
        }
      }
    }

    if (seg.fetchCache) {
      lastFetchCache = seg.fetchCache;
      if (seg.fetchCache.startsWith('force-')) {
        forceFetchCache = seg.fetchCache;
      }
    }
  }

  // Resolve dynamic
  if (hasForceDynamic) {
    effectiveDynamic = 'force-dynamic';
  } else if (hasForceStatic) {
    effectiveDynamic = 'force-static';
  } else if (lastDynamic) {
    effectiveDynamic = lastDynamic;
  }

  // Resolve revalidate
  if (hasRevalidateZero) {
    effectiveRevalidate = 0;
  } else if (minPositiveRevalidate !== null) {
    effectiveRevalidate = minPositiveRevalidate;
  }

  // Resolve fetchCache
  if (forceFetchCache) {
    effectiveFetchCache = forceFetchCache;
  } else if (lastFetchCache) {
    effectiveFetchCache = lastFetchCache;
  }

  // Check conflicts
  let hasConflict = false;
  let conflictReason: string | undefined;

  if (hasForceStatic && hasForceDynamic) {
    hasConflict = true;
    conflictReason = 'Conflicting segment options: cannot combine force-static with force-dynamic in the same route hierarchy.';
  } else if (hasForceStatic && (effectiveRevalidate === 0 || effectiveFetchCache === 'force-no-store')) {
    hasConflict = true;
    conflictReason = 'Conflicting segment options: force-static cannot be paired with revalidate = 0 or force-no-store data fetching.';
  }

  // Classify routeMode
  let routeMode: 'static' | 'isr' | 'dynamic' = 'static';
  if (
    effectiveDynamic === 'force-dynamic' ||
    effectiveRevalidate === 0 ||
    effectiveFetchCache === 'force-no-store'
  ) {
    routeMode = 'dynamic';
  } else if (typeof effectiveRevalidate === 'number' && effectiveRevalidate > 0) {
    routeMode = 'isr';
  } else {
    routeMode = 'static';
  }

  return {
    effectiveDynamic,
    effectiveRevalidate,
    effectiveFetchCache,
    routeMode,
    hasConflict,
    conflictReason,
  };
}

next-after-lifecycle-deferred.promptSeed:
# Next.js 15: Background Work with the after() API

## Description
In Next.js 15, the `after()` API (`next/server`) enables scheduling secondary asynchronous work to execute **after** the response has been returned or finished streaming. This prevents slow side effects (such as audit logging, telemetry, email dispatch, or cache invalidation) from increasing user-perceived response latency.

Implement an App Router Route Handler `POST` that validates an order request, commits the order synchronously, queues non-blocking background tasks via `after()`, and immediately returns an HTTP 201 response.

```ts
interface OrderPayload {
  orderId: string;
  customerEmail: string;
  amount: number;
}

interface ProcessedOrderResult {
  id: string;
  status: 'confirmed' | 'pending';
  total: number;
}

interface AuditLogRecord {
  timestamp: number;
  action: string;
  orderId: string;
  status: 'success' | 'failed';
}

// Injected scope services:
declare function processOrder(order: OrderPayload): Promise<ProcessedOrderResult>;
declare function sendOrderReceipt(email: string, orderId: string): Promise<void>;
declare function recordAuditLog(entry: AuditLogRecord): Promise<void>;
declare function after(task: (() => void | Promise<void>) | Promise<any>): void;
```

### POST(request: Request): Promise<NextResponse>

#### Requirements
1. **Request Body Parsing & Validation**:
   - Parse JSON from `request.json()`.
   - Validate that `orderId` is a non-empty string, `customerEmail` is a non-empty string containing `'@'`, and `amount` is a number strictly greater than 0.
   - If invalid or if JSON parsing fails, immediately return `NextResponse.json({ error: 'Invalid order payload' }, { status: 400 })`. Do **not** call `processOrder` or schedule any `after()` tasks.
2. **Order Processing**:
   - Call `const result = await processOrder({ orderId, customerEmail, amount })`.
   - If `processOrder` rejects or throws an error, catch it and return `NextResponse.json({ error: 'Order processing failed' }, { status: 500 })`. Do **not** schedule `after()` tasks on failure.
3. **Deferred Execution via `after()`**:
   - Schedule an asynchronous task with `after(async () => { ... })`:
     - Dispatch customer receipt: `await sendOrderReceipt(customerEmail, result.id)`.
     - Dispatch audit log: `await recordAuditLog({ timestamp: Date.now(), action: 'order_processed', orderId: result.id, status: 'success' })`.
   - Wrap the operations inside the `after` callback in a `try...catch` block to ensure any secondary task failure is safely caught without unhandled rejections.
4. **Immediate Response**:
   - Return `NextResponse.json({ success: true, orderId: result.id, status: result.status }, { status: 201 })`.
   - The response must be returned immediately without awaiting the `after()` tasks.

